<?php $editing = !empty($editCenter); $centerValue = static fn(string $key, mixed $default = '') => htmlspecialchars((string) ($editCenter->$key ?? $default)); ?>
<section class="hero-row compact-hero"><div><span class="eyebrow">Organização</span><h2 class="page-heading">Centros de custo</h2><p class="page-subtitle">Separe seus gastos por casa, empresa, carro ou projeto.</p></div></section>
<div class="catalog-layout"><section class="panel"><div class="panel-heading"><div><span class="eyebrow"><?= $editing ? 'Editar centro' : 'Novo centro' ?></span><h3><?= $editing ? 'Atualizar centro de custo' : 'Adicionar centro de custo' ?></h3></div></div><form method="post" action="<?= $editing ? '/centros-custo/' . (int) $editCenter->id . '/atualizar' : '/centros-custo' ?>" class="inline-form"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><label class="field"><span>Nome</span><input type="text" name="name" value="<?= $centerValue('name') ?>" placeholder="Ex.: Casa" maxlength="120" required></label><label class="field"><span>Código <em>opcional</em></span><input type="text" name="code" value="<?= $centerValue('code') ?>" placeholder="Ex.: CAS" maxlength="40"></label><label class="field field-wide"><span>Descrição <em>opcional</em></span><input type="text" name="description" value="<?= $centerValue('description') ?>" maxlength="255"></label><div class="form-actions"><button class="button button-primary" type="submit"><?= $editing ? 'Salvar centro' : 'Adicionar' ?></button><?php if ($editing): ?><a class="button button-ghost" href="/centros-custo">Cancelar</a><?php endif; ?></div></form></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Centros disponíveis</span><h3><?= count($costCenters) ?> centros</h3></div></div><div class="catalog-list"><?php foreach ($costCenters as $center): ?><div class="catalog-item"><span class="category-dot center-dot"></span><div><strong><?= htmlspecialchars($center->name) ?></strong><small><?= htmlspecialchars($center->code ?: 'Sem código') ?><?= $center->description ? ' · ' . htmlspecialchars($center->description) : '' ?><?= $center->user_id === null ? ' · padrão' : '' ?></small></div><span class="status-badge status-<?= $center->status ?>"><?= $center->status === 'active' ? 'Ativo' : 'Inativo' ?></span><?php if ($center->user_id !== null): ?><details class="action-menu"><summary>•••</summary><div class="action-popover"><a href="/centros-custo?edit=<?= (int) $center->id ?>">Editar</a><form method="post" action="/centros-custo/<?= (int) $center->id ?>/toggle"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit"><?= $center->status === 'active' ? 'Desativar' : 'Ativar' ?></button></form><form method="post" action="/centros-custo/<?= (int) $center->id ?>/excluir" data-confirm="Excluir este centro de custo?"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit" class="danger-text">Excluir</button></form></div></details><?php endif; ?></div><?php endforeach; ?></div></section></div>
